"""Pure logical constructors/comparison. No file, Git, oracle or case access."""
from copy import deepcopy
STATES=('known','missing','unknown','conflict','stale')
ABSENT=object()
B01_REASON='原sourceで確認した合成値。実資格/実承認ではない。'
B01_QUAL_REASON='依存する原source資格が未成立。空/falseや他ownerの成功で補完しない。'
GROUND_REASON='独立意味所見と原材料/対象の対応を比較した論理条件。実資格/実research/実承認ではない。'
NORMAL='当該工程/actionが指定した条件と委任内具体化を別々に保持する。'
QUAL='依存する独立原資料資格が未成立。未知を空/false/他owner成功で補わない。'
DEFINITION='当該action/必要条件の原定義が欠落/不明/不一致。既定集合や他actionの条件を補完しない。'
CONDITION='当該必要条件の原資料内容・kind・revision/scope不足を個別保持し、他条件を消さない。'
QCONDITION='当該必要条件の独立資格が未成立。他の既知条件を保持する。'
def pv(state,value,ref,reason):return {'state':state,'value':deepcopy(value)if state=='known'else None,'source_packet_ref':deepcopy(ref),'reason':reason}
def merge(states):
 bad={s for s in states if s!='known'}
 return 'known'if not bad else next(iter(bad))if len(bad)==1 else'unknown'
def qual(a,key):return a['qualification_sources'].get(key,{}).get('state','missing')
def dep(a,keys):return merge([qual(a,'carrier')]+[qual(a,k)for k in keys])
def obs(x):
 if not isinstance(x,dict):return'conflict',None
 s=x.get('state')
 if s=='value':return'known',x.get('value')
 return {'absent':'missing','null':'unknown','wrong_kind':'conflict'}.get(s,'conflict'),None
def eq(a,b):
 if a is ABSENT or b is ABSENT:return a is b
 if isinstance(a,bool)or isinstance(b,bool):return type(a)==type(b)and a==b
 if isinstance(a,dict)and isinstance(b,dict):return set(a)==set(b)and all(eq(a[k],b[k])for k in a)
 if isinstance(a,list)and isinstance(b,list):return len(a)==len(b)and all(eq(x,y)for x,y in zip(a,b))
 return a==b
def logical(role,root='B01'):return {'kind':'contract_role_owner','contract_ref':'HARNESS-L4-003-'+root,'role':role}
def mreturn(a,field,state,reason,owner=None,layer=None,refs=None):
 ref=a['context']['assessment_input_ref']
 return {'affected_field':field,'cause_state':state,'original_source_refs':deepcopy(refs or[]),
 'affected_target':pv('known',a['original']['target'],ref,'原資料の対象revision/scopeを保持する。'),
 'return_layer':pv('known',layer,ref,'原資料が指定した意味戻し層を保持する。')if layer is not None else pv('unknown',None,ref,'原資料は戻し層を指定していない。'),
 'logical_owner_reference':pv('known',owner,ref,'既存L4の責務に結ぶ論理owner role。実配送先/実資格ではない。')if owner is not None else pv('unknown',None,ref,'当該原資料に論理owner参照が未供給。別ownerで補完しない。'),
 'reason':reason,'operation_effect':'none'}
def source_refs(a,key,payload):
 r=a['qualification_sources'].get(key,{}).get('source_ref')
 return [deepcopy(r)]if payload is not None and isinstance(r,dict)else[]
def value_at(v,path):
 for k in path:
  try:v=v[k]
  except(KeyError,IndexError,TypeError):return ABSENT
 return v
def observed(value):
 if value is ABSENT:return {'state':'absent'}
 if value is None:return {'state':'null'}
 return {'state':'value','value':deepcopy(value)}
def cdiff(out,path,old,new,reason,proposed_observation=None):out.append({'path':deepcopy(path),'state':'conflict','source_observation':observed(old),'proposed_value':deepcopy(proposed_observation)if proposed_observation is not None else observed(new),'reason':reason})
def compare_json(out,path,a,b):
 if eq(a,b):return
 if isinstance(a,dict)and isinstance(b,dict):
  for k in list(a)+[k for k in b if k not in a]:compare_json(out,path+[k],a.get(k,ABSENT),b.get(k,ABSENT))
 else:cdiff(out,path,a,b,'候補の当該宣言は元assessmentの値/状態へ対応しない。')
def compare_pv(out,path,a,b):
 if a['state']!=b['state']:cdiff(out,path,a,b,'候補の当該宣言は元assessmentの値/状態へ対応しない。')
 elif path==['partial_values','condition_results']and a['state']=='known':
  for k in list(a['value'])+[k for k in b['value']if k not in a['value']]:
   if k in a['value']and k in b['value']:compare_pv(out,path+['value',k],a['value'][k],b['value'][k])
   else:cdiff(out,path+['value',k],a['value'].get(k,ABSENT),b['value'].get(k,ABSENT),'候補の当該宣言は元assessmentの値/状態へ対応しない。')
 else:compare_json(out,path+['value'],a['value'],b['value'])
 if not eq(a['source_packet_ref'],b['source_packet_ref']):cdiff(out,path+['source_packet_ref'],a['source_packet_ref'],b['source_packet_ref'],'候補の出典参照は現在の比較入力carrierへ対応しない。')
 if a['reason']!=b['reason']:cdiff(out,path+['reason'],a['reason'],b['reason'],'候補の説明文は現在のbase理由構成へ対応しない。')
def compare_claims(w,claims):
 if claims is None:return {'state':'not_proposed','differences':[]}
 out=[]
 for claim in claims:
  path=claim['path'];tag=claim['proposed_value'];actual=value_at(w,path)
  if tag['state']=='wrong_kind':cdiff(out,path,actual,ABSENT,'候補の当該宣言は元assessmentの値/状態へ対応しない。',tag);continue
  proposed=tag['value']if tag['state']=='value'else None if tag['state']=='null'else ABSENT
  if claim['kind']=='partial_record'and isinstance(actual,dict)and isinstance(proposed,dict):compare_pv(out,path,actual,proposed)
  else:compare_json(out,path,actual,proposed)
 return {'state':'compared','differences':out}
def finish(a,p,returns,readable,diagnostics,definition=None):
 w={'partial_values':p,'owner_returns':returns,'source_qualification_results':{k:v['state']for k,v in a['qualification_sources'].items()},'qualification_returns':diagnostics,'definition_return':{'state':'absent'}if definition is None else{'state':'present','value':definition},'readable_original_materials':readable,'candidate_comparison':{'state':'not_proposed','differences':[]},'unaffected_scope':deepcopy(a['unaffected_scope']),'operation_effect':'none'}
 w['candidate_comparison']=compare_claims(w,a['candidate_claims']);return w
